def base64encode(s):
    if isinstance(s, string_types):
        s = s.encode("utf-8")

    encoded = base64.urlsafe_b64encode(s).rstrip(b"\n=")
    try:
        encoded = encoded.decode("utf-8")
    except UnicodeDecodeError:
        pass
    return encoded

